import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"3 个值得使用的首次亮相在 Python 3.0 中的特性 | LCTT x X-CMD","titleTemplate":false,"description":"3 个值得使用的首次亮相在 Python 3.0 中的特性 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 个值得使用的首次亮相在 Python 3.0 中的特性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 个值得使用的首次亮相在 Python 3.0 中的特性 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210512 3 features that debuted in Python 3.0 you should use now","title":"3 个值得使用的首次亮相在 Python 3.0 中的特性","tag":"202105","desc":""},"relativePath":"202105/20210512 3 features that debuted in Python 3.0 you should use now.md","filePath":"[post].md"}'),h={name:"202105/20210512 3 features that debuted in Python 3.0 you should use now.md"};function u(c,s,g,k,b,f){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="_3-个值得使用的首次亮相在-python-3-0-中的特性" tabindex="-1">3 个值得使用的首次亮相在 Python 3.0 中的特性 <a class="header-anchor" href="#_3-个值得使用的首次亮相在-python-3-0-中的特性" aria-label="Permalink to “3 个值得使用的首次亮相在 Python 3.0 中的特性”">​</a></h1><blockquote><p>探索一些未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/20/103117me72dllr6lebk1fv.jpg" alt=""></p><p>这是 Python 3.x 首发特性系列文章的第一篇。Python 3.0 于 2008 年首次发布，尽管它已经发布了一段时间，但它引入的许多特性都没有被充分利用，而且相当酷。这里有三个你应该知道的。</p><h3 id="仅限关键字参数" tabindex="-1">仅限关键字参数 <a class="header-anchor" href="#仅限关键字参数" aria-label="Permalink to “仅限关键字参数”">​</a></h3><p>Python 3.0 首次引入了<strong>仅限关键字参数</strong>参数的概念。在这之前，不可能指定一个只通过关键字传递某些参数的 API。这在有许多参数，其中一些参数可能是可选的函数中很有用。</p><p>请看一个特意设计的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def show_arguments(base, extended=None, improved=None, augmented=None):</span></span>
<span class="line"><span>    print(&quot;base is&quot;, base)</span></span>
<span class="line"><span>    if extended is not None:</span></span>
<span class="line"><span>        print(&quot;extended is&quot;, extended)</span></span>
<span class="line"><span>    if improved is not None:</span></span>
<span class="line"><span>        print(&quot;improved is&quot;, improved)</span></span>
<span class="line"><span>    if augmented is not None:</span></span>
<span class="line"><span>        print(&quot;augmented is&quot;, augmented)</span></span></code></pre></div><p>当阅读调用该函数的代码时，有时很难理解发生了什么：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show_arguments(&quot;hello&quot;, &quot;extra&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    base is hello</span></span>
<span class="line"><span>    extended is extra</span></span>
<span class="line"><span></span></span>
<span class="line"><span>show_arguments(&quot;hello&quot;, None, &quot;extra&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    base is hello</span></span>
<span class="line"><span>    improved is extra</span></span></code></pre></div><p>虽然可以用关键字参数来调用这个函数，但这明显不是最好的方法。相反，你可以将这些参数标记为仅限关键字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def show_arguments(base, *, extended=None, improved=None, augmented=None):</span></span>
<span class="line"><span>    print(&quot;base is&quot;, base)</span></span>
<span class="line"><span>    if extended is not None:</span></span>
<span class="line"><span>        print(&quot;extended is&quot;, extended)</span></span>
<span class="line"><span>    if improved is not None:</span></span>
<span class="line"><span>        print(&quot;improved is&quot;, improved)</span></span>
<span class="line"><span>    if augmented is not None:</span></span>
<span class="line"><span>        print(&quot;augmented is&quot;, augmented)</span></span></code></pre></div><p>现在，你不能用位置参数传入额外的参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show_arguments(&quot;hello&quot;, &quot;extra&quot;)</span></span>
<span class="line"><span>    ---------------------------------------------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    TypeError                                 Traceback (most recent call last)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;ipython-input-7-6000400c4441&gt; in &lt;module&gt;</span></span>
<span class="line"><span>    ----&gt; 1 show_arguments(&quot;hello&quot;, &quot;extra&quot;)</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    TypeError: show_arguments() takes 1 positional argument but 2 were given</span></span></code></pre></div><p>对该函数的有效调用更容易预测：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>show_arguments(&quot;hello&quot;, improved=&quot;extra&quot;)</span></span>
<span class="line"><span>    base is hello</span></span>
<span class="line"><span>    improved is extra</span></span></code></pre></div><h3 id="nonlocal" tabindex="-1">nonlocal <a class="header-anchor" href="#nonlocal" aria-label="Permalink to “nonlocal”">​</a></h3><p>有时，函数式编程的人根据编写累加器的难易程度来判断一种语言。累加器是一个函数，当它被调用时，返回目前为止发给它的所有参数的总和。</p><p>在 3.0 之前，Python 的标准答案是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class _Accumulator:</span></span>
<span class="line"><span>    def __init__(self):</span></span>
<span class="line"><span>        self._so_far = 0</span></span>
<span class="line"><span>    def __call__(self, arg):</span></span>
<span class="line"><span>        self._so_far += arg</span></span>
<span class="line"><span>        return self._so_far</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def make_accumulator():</span></span>
<span class="line"><span>    return _Accumulator()</span></span></code></pre></div><p>虽然我承认有些啰嗦，但这确实有效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>acc = make_accumulator()</span></span>
<span class="line"><span>print(&quot;1&quot;, acc(1))</span></span>
<span class="line"><span>print(&quot;5&quot;, acc(5))</span></span>
<span class="line"><span>print(&quot;3&quot;, acc(3))</span></span></code></pre></div><p>这样做的输出结果将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1 1</span></span>
<span class="line"><span>5 6</span></span>
<span class="line"><span>3 9</span></span></code></pre></div><p>在 Python 3.x 中，<code>nonlocal</code> 关键字可以用少得多的代码实现同样的行为。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def make_accumulator():</span></span>
<span class="line"><span>    so_far = 0</span></span>
<span class="line"><span>    def accumulate(arg):</span></span>
<span class="line"><span>        nonlocal so_far</span></span>
<span class="line"><span>        so_far += arg</span></span>
<span class="line"><span>        return so_far</span></span>
<span class="line"><span>    return accumulate</span></span></code></pre></div><p>虽然累加器是人为的例子，但使用 <code>nonlocal</code> 关键字使内部函数拥有具有状态的的能力是一个强大的工具。</p><h3 id="扩展析构" tabindex="-1">扩展析构 <a class="header-anchor" href="#扩展析构" aria-label="Permalink to “扩展析构”">​</a></h3><p>想象一下，你有一个 CSV 文件，每一行由几个元素组成：</p><ul><li>第一个元素是年份</li><li>第二个元素是月</li><li>其他元素是该月发表的全部文章数，每天一个条目</li></ul><p>请注意，最后一个元素是 <em>文章总数</em>，而不是 <em>每天发表的文章</em>。例如，一行的开头可以是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2021,1,5,8,10</span></span></code></pre></div><p>这意味着在 2021 年 1 月，第一天发表了 5 篇文章。第二天，又发表了三篇文章，使总数达到 8 篇。第三天，又发表了两篇文章。</p><p>一个月可以有 28 天、30 天或 31 天。提取月份、日期和文章总数有多难？</p><p>在 3.0 之前的 Python 版本中，你可能会这样写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>year, month, total = row[0], row[1], row[-1]</span></span></code></pre></div><p>这是正确的，但它掩盖了格式。使用<strong>扩展析构</strong>，同样可以这样表达：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>year, month, *rest, total = row</span></span></code></pre></div><p>这意味着如果该格式改为前缀了一个描述，你可以把代码改成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_, year, month, *rest, total = row</span></span></code></pre></div><p>而不需要在每个索引中添加 <code>1</code>。</p><h3 id="接下来是什么" tabindex="-1">接下来是什么？ <a class="header-anchor" href="#接下来是什么" aria-label="Permalink to “接下来是什么？”">​</a></h3><p>Python 3.0 和它的后期版本已经推出了 12 年多，但是它的一些功能还没有被充分利用。在本系列的下一篇文章中，我将会写另外三个。</p><hr>`,44)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/python-30-features"},{default:t(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/5/python-30-features",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const _=p(h,[["render",u]]);export{x as __pageData,_ as default};
